package application.domain.services.fulfillment;
import application.domain.model.*; import application.domain.ports.in.*; import application.domain.ports.out.*; import application.domain.services.ServiceSupport; import application.domain.exceptions.*; import java.math.*; import java.util.*;
public class ProcessRefundService implements ProcessRefundUseCase { private final ReturnRequestRepositoryPort returns; private final RefundRepositoryPort refunds; private final OrderRepositoryPort orders; private final OperationAuditPort audit; public ProcessRefundService(ReturnRequestRepositoryPort r,RefundRepositoryPort f,OrderRepositoryPort o,OperationAuditPort a){returns=r;refunds=f;orders=o;audit=a;}
 public Refund processRefund(User actor,String rid,String fid){ServiceSupport.role(actor,"ADMIN","EMPLOYEE");ReturnRequest r=ServiceSupport.required(returns.findById(rid),"ReturnRequest",rid);if(!r.isApproved())throw new DomainRuleException("Return must be approved");Order o=r.getOrder();BigDecimal amount=o.getItems().stream().filter(i->r.getProduct()==null||i.product().getId().equals(r.getProduct().getId())).map(OrderItem::total).reduce(BigDecimal.ZERO,BigDecimal::add);Refund saved=refunds.save(new Refund(fid,r,amount));o.changeStatus(DomainTypes.OrderStatus.REFUNDED);orders.update(o);audit.record(actor,"PROCESS_REFUND",fid,Map.of("returnId",rid,"amount",amount));return saved;}
}
